def formatParagraphs(paragraphs):
    TAG = {'bold': 'b', 'italic': 'i', 'underline': 'u', 'p': None}

    def render(chunk):
        kind, content = chunk[0], chunk[1]
        # content 可以是纯文本，也可以是嵌套的 chunk 列表
        if isinstance(content, list):
            inner = ''.join(render(c) for c in content)
        else:
            inner = content
        tag = TAG.get(kind)
        return f'<{tag}>{inner}</{tag}>' if tag else inner

    return ['<p>' + ''.join(render(c) for c in para) + '</p>' for para in paragraphs]
